 async function applyDeviceConnection(data){
  const revision=++discoveryRevision.current;
  setSettings(s=>({...s,...deviceConnectionPatch(data)}));
  setManager(null);setQuota(null);setManagerError('');setConnection('');setApiModels([]);setNotebookModels([]);setNotebookInfo(null);setModelReadNote('');
  notify('Device connected. Addresses and keys were saved securely.');
  try{const snapshot=await jsonBridge('manager_status',data.manager_url,data.manager_key);if(revision!==discoveryRevision.current)return;setManager(snapshot);
   try{const declared=await jsonBridge('manager_models',data.manager_url,data.manager_key);if(revision!==discoveryRevision.current)return;const models=managerModelList(snapshot,declared.models);setNotebookModels(models);setNotebookInfo(declared.notebook||null);setSettings(s=>({...s,...modelSelections(s,models),modelId:selectDiscoveredModel(data.model_id||snapshot.config?.model_alias,discoveredModels([],models))}))}catch{}
   try{const q=await jsonBridge('manager_quota',data.manager_url,data.manager_key);if(revision===discoveryRevision.current)setQuota(q)}catch{}
  }catch(e){if(revision===discoveryRevision.current)setManagerError(e.message)}
 }
 async function deploymentDeleted(m){const url='https://'+m.worker+'.'+m.subdomain+'.workers.dev';try{if(JSON.parse(localStorage.getItem('studio-installation')||'{}').id===m.id)localStorage.removeItem('studio-installation')}catch{}if(settings.managerUrl===url){if(saveKeys({...readKeys(),managerKey:'',modelKey:''})===false)throw Error('Local keys could not be cleared. Retry.');discoveryRevision.current++;setSettings(s=>({...s,managerUrl:'',modelUrl:'',managerKey:'',modelKey:'',modelId:''}));setManager(null);setQuota(null);setManagerError('')}notify(settings.language==='zh-CN'?'所选部署已删除。':'Selected deployment deleted.');}
 async function clearKeys(){
  if(busy||running)return;
  const revision=++discoveryRevision.current,snapshot={...settings};setBusy('clear-keys');setKeyClearError('');
  try{
   await clearSetupCredentials();
   const cleared=await clearServiceKeys(snapshot);
   if(revision!==discoveryRevision.current){notify('Connection changed. Current saved keys were kept.');return}
   // Persist immediately after remote deletion, before displaying success.
   const next={...snapshot,...cleared};if(saveKeys(cleared)===false)throw Error('Cloud authorization was deleted, but local keys could not be cleared. Try clearing again.');
   setSettings(next);setManager(null);setQuota(null);setManagerError('');setConnection('');setApiModels([]);setNotebookModels([]);setNotebookInfo(null);setModelReadNote('');
   notify(snapshot.managerKey?.startsWith('studio_admin_')?'This device authorization was deleted and local service keys were cleared.':'Service keys cleared.');
  }catch(e){setKeyClearError('Could not finish clearing keys. Saved keys were kept so you can retry. '+e.message)}finally{setBusy('')}
 }
